SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'DMF0048' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0048_dayRange_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_main_COLUMN_SETUP' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_main_EXCEL' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_main_FILTER' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_main_MEASURE_SELECT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_main_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_main_SORT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_spreadTitle_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_titleSet_RESET' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_titleSet_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0048_titleSet_SEARCH' API_ID FROM DUAL) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
