   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0048' MNU_ID, 'Sales Monitoring' SHT_NM, 'COLUMN_SETUP' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0048' MNU_ID, 'Sales Monitoring' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
